# Writes bench/typed.ts: typed arrays, one block per element kind. Run from tools/iron_ts_tests:
#   python3 bench/gen_typed_program.py && python3 bench/add_module.py typed ty 30000 313
import os

os.chdir(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
KINDS = ["Int8Array", "Uint8Array", "Uint8ClampedArray", "Int16Array", "Uint16Array", "Int32Array", "Uint32Array", "Float32Array", "Float64Array"]
src = '''// Typed arrays, one block per element kind. Every exported function without parameters returns a
// string; `gen_typed_expected.ts` runs this file in bun. Generated by bench/gen_typed_program.py.

function fail(f: () => string): string {
  try {
    return f();
  } catch (e) {
    return (e as Error).name + ": " + (e as Error).message;
  }
}

const VALUES = [-1, 0.5, 1.5, 2.5, 3.5, 127.5, 128, 255, 255.5, 256, 257.7, -129, 32768, 65535, 65536, 2147483648, 4294967295, 4294967296, 4294967301, 1e10, 3.14159, 0.1, 16777217, -0.4, 1e40, NaN, Infinity, -Infinity];

'''
for K in KINDS:
    src += f'''export function {K}_stores(): string {{
  const a = new {K}(VALUES.length);
  for (let i = 0; i < VALUES.length; i++) a[i] = VALUES[i];
  return a.join(",") + "|" + a.length + "|" + a.byteLength;
}}

export function {K}_make(): string {{
  const a = new {K}([1, 2.7, -3, 300, 70000]);
  const b = new {K}(a);
  const c = new {K}(3);
  const d = {K}.from([9, 8, 7]);
  const e = new {K}();
  const f = new {K}(new Float64Array([1.5, -2.5, 1e5]));
  return [a.join(), b.join(), c.join(), d.join(), String(e.length), f.join(), String(a.length), a.toString()].join("|");
}}

export function {K}_methods(): string {{
  const a = new {K}([5, 3, 9, 1, 7, 3]);
  let sum = 0;
  a.forEach((v, i) => {{ sum += v * (i + 1); }});
  const m = a.map((v) => v * 2);
  const f = a.filter((v) => v > 3);
  const s = a.slice(1, -1);
  const s2 = a.slice(-2);
  const r = a.reduce((x, y) => x + y, 0);
  const rr = a.reduceRight((x, y) => x * 10 + y, 0);
  return [
    String(sum), m.join(), f.join(), s.join(), s2.join(), String(r), String(rr), String(a.indexOf(3)), String(a.lastIndexOf(3)), String(a.includes(9)),
    String(a.includes(100)), String(a.find((v) => v > 5)), String(a.findIndex((v) => v > 5)), String(a.some((v) => v === 1)), String(a.every((v) => v > 0)),
    String(a.at(-1)), String(a.at(0)), a.join("-"),
  ].join("|");
}}

export function {K}_inplace(): string {{
  const a = new {K}(8);
  a.fill(7);
  const b = a.join();
  a.fill(1, 2, 5);
  const c = a.join();
  a.fill(9, -2);
  const d = a.join();
  a.set([1, 2, 3], 2);
  const e = a.join();
  a.set(new {K}([4, 5]), 6);
  const f = a.join();
  const g = new {K}([3, 1, 2, 10, 20, 100]);
  g.sort();
  const h = g.join();
  g.reverse();
  const i = g.join();
  g.sort((x, y) => y - x);
  const j = g.join();
  const k = new {K}([5, 4, 6]).toSorted().join() + "/" + new {K}([5, 4, 6]).toReversed().join();
  return [b, c, d, e, f, h, i, j, k].join("|");
}}

export function {K}_iterate(): string {{
  const a = new {K}([10, 20, 30]);
  let out = "";
  for (const v of a) out += v + ";";
  const spread = [...a];
  let idx = "";
  for (let i = 0; i < a.length; i++) idx += a[i] + ",";
  a[5] = 99;
  return out + "|" + spread.length + "|" + idx + "|" + a.length;
}}

'''
src += '''export function setErrors(): string {
  return [
    fail(() => { new Uint8Array(2).set([1, 2, 3]); return "ok"; }),
    fail(() => { new Float32Array(4).set(new Float32Array(3), 2); return "ok"; }),
    fail(() => { new Int8Array(4).set([1], -1); return "ok"; }),
  ].join("|");
}

export function floatSorting(): string {
  const a = new Float64Array([3, -1, NaN, 0, -0, 2.5, Infinity, -Infinity]);
  a.sort();
  const b = new Float32Array([0.1, 0.2, 0.30000001192092896, 16777216, 16777217]);
  return a.join() + "|" + b.join() + "|" + b[0] + "|" + (b[0] === 0.1) + "|" + Math.fround(0.1);
}
'''
open("bench/typed.ts", "w", encoding="utf8").write(src)
print(len(src))
